-- FLL-GAR-2023 · coverage wave block 2b (2026-09-29): GATE PROPOSALS that read the block-2a fields. SIGN-OFF REQUIRED (Alvaro):
-- every statement here changes enforcement (new gates, extended/relaxed conditions, two re-hosts, two severity proposals) — none is pre-authorised.
-- Quotes = rendered PDF pages read in-session 2026-09-29 (VA). Each item carries its print basis and its open RULING in the comment above it.
-- Apply ONLY after block 2a (fields must exist) and only after the rulings are settled: node scripts/apply-migration.mjs scripts/migrations/20260929210100_fll_gar_2023_gates_coverage_block2b.sql
-- Rollback: scripts/migrations/rollback-20260929210100_fll_gar_2023_gates_coverage_block2b.sql
BEGIN;
-- FLL-GAR-10 REQ-12
-- Tab. 3 row 7 (p. 37): "wPr ≤ w ≤ w0,97Pr — bei w ≤ wPr: Luftporenanteil na ≤ 5 %". RULING: whether w < wPr is admissible at all (with na ≤ 5 %) or only w = wPr — the print is ambiguous; the OR form above reads the second line as the admissible dry case.
UPDATE compliance_requirements cr SET condition = 'IF abdichtungs_art == mineralisch_ohne_zusatzstoffe THEN kornanteil_unter_2micron >= 15 AND organische_substanz_VGL <= 5 AND kalkgehalt_VCA <= 15 AND kf_abdichtung <= 0.000000001 AND verdichtungsgrad_Dpr >= 97 AND ((w_pr_pct <= einbauwassergehalt_w_pct AND einbauwassergehalt_w_pct <= w_097pr_pct) OR (einbauwassergehalt_w_pct <= w_pr_pct AND luftporenanteil_na_pct <= 5))', source_quote = 'Tab. 3 row 7 (p. 37): "wPr ≤ w ≤ w0,97Pr — bei w ≤ wPr: Luftporenanteil na ≤ 5 %". RULING: whether w < wPr is admissible at all (with na ≤ 5 %) or only w = wPr — the print is ambiguous; the OR form above reads the second line as the admissible dry case.'
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE cr.worksheet_template_id = w.id AND w.code = 'FLL-GAR-10' AND s.code = 'FLL-GAR-2023' AND cr.code = 'REQ-12' AND cr.condition = 'IF abdichtungs_art == mineralisch_ohne_zusatzstoffe THEN kornanteil_unter_2micron >= 15 AND organische_substanz_VGL <= 5 AND kalkgehalt_VCA <= 15 AND kf_abdichtung <= 0.000000001 AND verdichtungsgrad_Dpr >= 97';
-- FLL-GAR-10 REQ-20
-- Tab. 24 (p. 95) rows 6–10 added; the guard "pe_werkstoff == PEHD" mirrors the table title "für Bahnen aus PEHD" (the old gate applied PEHD limits to PELD too). RULING: PELD case — Tab. 24 prints no PELD limits; §6.4.1.1 requires the FLL root-resistance evidence for PELD instead (REQ-11).
UPDATE compliance_requirements cr SET condition = 'IF abdichtungs_art == bahn_pe AND pe_werkstoff == PEHD THEN peeh_dichte_g_cm3 > 0.940 AND peeh_mfr >= 1.0 AND peeh_mfr <= 3.0 AND peeh_russgehalt_pct >= 2 AND peeh_russgehalt_pct <= 3 AND peeh_russverteilung_kat >= 2 AND peeh_russverteilung_kat <= 3 AND peeh_massaenderung_pct <= 2 AND peeh_nctl_h > 500 AND peeh_oit_min > 100 AND peeh_bbodschv_unbedenklich == true', source_quote = 'Tab. 24 (p. 95) rows 6–10 added; the guard "pe_werkstoff == PEHD" mirrors the table title "für Bahnen aus PEHD" (the old gate applied PEHD limits to PELD too). RULING: PELD case — Tab. 24 prints no PELD limits; §6.4.1.1 requires the FLL root-resistance evidence for PELD instead (REQ-11).'
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE cr.worksheet_template_id = w.id AND w.code = 'FLL-GAR-10' AND s.code = 'FLL-GAR-2023' AND cr.code = 'REQ-20' AND cr.condition = 'IF abdichtungs_art == bahn_pe THEN peeh_dichte_g_cm3 > 0.940 AND peeh_mfr >= 1.0 AND peeh_mfr <= 3.0 AND peeh_russgehalt_pct >= 2 AND peeh_russgehalt_pct <= 3';
-- FLL-GAR-10 REQ-18 → re-hosted to FLL-GAR-16
-- §6.2.1.2 (p. 84): "Mindestdicke von 1,2 mm … werkseitig vorkonfektionierten Bahnen für gering beanspruchte Nutzungen (z. B. Gartenteiche) … ≥ 1,0 mm zulässig". bahnendicke_min_mm (FLL-GAR-16-D2) already derives 1,0 / 1,2 from bahn_vorkonfektioniert. Re-hosted to FLL-GAR-16 where all inputs live. Source-settled in substance; it relaxes enforcement for the prefab case → sign-off.
UPDATE compliance_requirements cr SET condition = 'IF abdichtungs_art == bahn_kunststoff_elastomer THEN bahnendicke_mm >= bahnendicke_min_mm', worksheet_template_id = (SELECT w2.id FROM worksheet_templates w2 WHERE w2.standard_id = s.id AND w2.code = 'FLL-GAR-16'), source_quote = '§6.2.1.2 (p. 84): "Mindestdicke von 1,2 mm … werkseitig vorkonfektionierten Bahnen für gering beanspruchte Nutzungen (z. B. Gartenteiche) … ≥ 1,0 mm zulässig". bahnendicke_min_mm (FLL-GAR-16-D2) already derives 1,0 / 1,2 from bahn_vorkonfektioniert. Re-hosted to FLL-GAR-16 where all inputs live. Source-settled in substance; it relaxes enforcement for the prefab case → sign-off.'
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE cr.worksheet_template_id = w.id AND w.code = 'FLL-GAR-10' AND s.code = 'FLL-GAR-2023' AND cr.code = 'REQ-18' AND cr.condition = 'IF abdichtungs_art == bahn_kunststoff_elastomer THEN bahnendicke_mm >= 1.2';
-- FLL-GAR-10 REQ-22 → re-hosted to FLL-GAR-20
-- §7.2.1.1/§7.2.1.2/§7.2.2.1 (p. 103–104), all "soll" → severity stays warn. The old gate read schichtdicke_abdichtung_cm of the mineral sheet (hidden for silicates) — never satisfiable; now its own field on FLL-GAR-20.
UPDATE compliance_requirements cr SET condition = 'IF abdichtungs_art == alkalisilikat THEN as_schichtdicke_cm >= 25 AND feinkornanteil_063_pct >= 20 AND as_lockerungstiefe_cm >= 25', worksheet_template_id = (SELECT w2.id FROM worksheet_templates w2 WHERE w2.standard_id = s.id AND w2.code = 'FLL-GAR-20'), source_quote = '§7.2.1.1/§7.2.1.2/§7.2.2.1 (p. 103–104), all "soll" → severity stays warn. The old gate read schichtdicke_abdichtung_cm of the mineral sheet (hidden for silicates) — never satisfiable; now its own field on FLL-GAR-20.'
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE cr.worksheet_template_id = w.id AND w.code = 'FLL-GAR-10' AND s.code = 'FLL-GAR-2023' AND cr.code = 'REQ-22' AND cr.condition = 'IF abdichtungs_art == alkalisilikat THEN schichtdicke_abdichtung_cm >= 25 AND feinkornanteil_063_pct >= 20';
-- FLL-GAR-22 REQ-11 · severity → block
-- §4.3 (p. 27): "Bei vorgesehener Bepflanzung ist die Eignung … durchzuführen … FLL-Testat rhizomfest gegen Quecken … Bei Beanspruchung durch wurzelaggressive und rhizombildende Pflanzenarten … zusätzliche Prüfung … erforderlich"; PEHD exemption §6.4.1.1 (p. 95): "Auf eine Prüfung der Wurzel- und Rhizomfestigkeit kann verzichtet werden." RULING: severity warn → block ("ist … durchzuführen", "erforderlich"); whether pflanzen_aggressiv_count (engineer-flagged rows on FLL-GAR-24) is the right trigger versus a Tab.-29 match.
UPDATE compliance_requirements cr SET condition = 'IF mit_bepflanzung == true THEN (abdichtungs_art == bahn_pe AND pe_werkstoff == PEHD) OR (wurzelfestigkeit_testat_quecken == true AND (pflanzen_aggressiv_count == 0 OR rhizomfestigkeit_gewaesser_pruefung == true))', severity = 'block', source_quote = '§4.3 (p. 27): "Bei vorgesehener Bepflanzung ist die Eignung … durchzuführen … FLL-Testat rhizomfest gegen Quecken … Bei Beanspruchung durch wurzelaggressive und rhizombildende Pflanzenarten … zusätzliche Prüfung … erforderlich"; PEHD exemption §6.4.1.1 (p. 95): "Auf eine Prüfung der Wurzel- und Rhizomfestigkeit kann verzichtet werden." RULING: severity warn → block ("ist … durchzuführen", "erforderlich"); whether pflanzen_aggressiv_count (engineer-flagged rows on FLL-GAR-24) is the right trigger versus a Tab.-29 match.'
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE cr.worksheet_template_id = w.id AND w.code = 'FLL-GAR-22' AND s.code = 'FLL-GAR-2023' AND cr.code = 'REQ-11' AND cr.condition = '';
-- FLL-GAR-22 REQ-24 · severity → block
-- §8.1 (p. 109) d ≤ 2 mm exemption; Tab. 26 (p. 111) sand minimum thickness per soil class ("anzuwenden", §8.4.1); Tab. 27 (p. 112) "gelten die Mindestanforderungen"; §8.3.2 (p. 113) Prüfzeugnis; §8.3 (p. 110) overlap ≥ 10 cm. RULING: soil classes whose Tab.-26 sand cell prints "-" (SE/SW/SI, and the x-only rows) make the lookup empty → the comparison stays pending; a per-material alternative (Vliesstoff/Bautenschutzmatte/Beton) needs a selection field that this block does not add.
UPDATE compliance_requirements cr SET condition = '(sl_baugrund_groesstkorn_mm <= 2 OR sl_schutzlage_unten_dicke_cm >= sl_schutzlage_unten_sand_min_cm) AND (swk_klasse IS NULL OR (sl_schutzlage_oben_flaechengewicht >= sl_schutzlage_oben_flaechengewicht_min AND sl_pruefzeugnis_swk == true)) AND sl_ueberlappung_cm >= 10', severity = 'block', source_quote = '§8.1 (p. 109) d ≤ 2 mm exemption; Tab. 26 (p. 111) sand minimum thickness per soil class ("anzuwenden", §8.4.1); Tab. 27 (p. 112) "gelten die Mindestanforderungen"; §8.3.2 (p. 113) Prüfzeugnis; §8.3 (p. 110) overlap ≥ 10 cm. RULING: soil classes whose Tab.-26 sand cell prints "-" (SE/SW/SI, and the x-only rows) make the lookup empty → the comparison stays pending; a per-material alternative (Vliesstoff/Bautenschutzmatte/Beton) needs a selection field that this block does not add.'
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE cr.worksheet_template_id = w.id AND w.code = 'FLL-GAR-22' AND s.code = 'FLL-GAR-2023' AND cr.code = 'REQ-24' AND cr.condition = '';
-- FLL-GAR-23 REQ-23
-- §4.8 (p. 32): "i. d. R. 30 cm … Durch Verwendung angepasster Randbefestigungen ist eine Reduzierung der Mindestüberhöhung der Abdichtung auf ≥ 15 cm möglich." Source-settled; relaxes enforcement for the fastening case → sign-off. Severity stays warn ("i. d. R.").
UPDATE compliance_requirements cr SET condition = 'freibord_zu_gelaende_cm >= 5 AND ((randbefestigung_angepasst == true AND freibord_zu_bauwerk_cm >= 15) OR freibord_zu_bauwerk_cm >= 30)', source_quote = '§4.8 (p. 32): "i. d. R. 30 cm … Durch Verwendung angepasster Randbefestigungen ist eine Reduzierung der Mindestüberhöhung der Abdichtung auf ≥ 15 cm möglich." Source-settled; relaxes enforcement for the fastening case → sign-off. Severity stays warn ("i. d. R.").'
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE cr.worksheet_template_id = w.id AND w.code = 'FLL-GAR-23' AND s.code = 'FLL-GAR-2023' AND cr.code = 'REQ-23' AND cr.condition = 'freibord_zu_gelaende_cm >= 5 AND freibord_zu_bauwerk_cm >= 30';
-- FLL-GAR-06 REQ-31 (new, block) — "erforderlich" → block (RULING).
INSERT INTO compliance_requirements (worksheet_template_id, code, title_de, title_en, condition, clause_reference, severity, description, source_quote, requires_attestation)
SELECT w.id, 'REQ-31', 'Baugrund — Verformungsmodul Ev2 ≥ 45 MPa und Ev2/Ev1 ≤ 2,5', 'Subgrade — deformation modulus Ev2 ≥ 45 MPa and Ev2/Ev1 ≤ 2.5', 'baugrund_ev2_mpa >= 45 AND baugrund_ev2_ev1 <= 2.5', 'Sec.4.6', 'block', 'Coverage block 2b (2026-09-29): "erforderlich" → block (RULING).', 'Für eine anforderungsgerechte Tragfähigkeit ist mindestens ein Verformungsmodul Ev2 ≥ 45 MPa (Ev2/Ev1 ≤ 2,5) erforderlich.', false
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE w.code = 'FLL-GAR-06' AND s.code = 'FLL-GAR-2023'
ON CONFLICT (worksheet_template_id, code) DO NOTHING;
-- FLL-GAR-06 REQ-32 (new, warn) — "soll" → warn.
INSERT INTO compliance_requirements (worksheet_template_id, code, title_de, title_en, condition, clause_reference, severity, description, source_quote, requires_attestation)
SELECT w.id, 'REQ-32', 'Baugrund — Verdichtungsgrad DPr ≥ 97 %', 'Subgrade — degree of compaction DPr ≥ 97 %', 'baugrund_dpr_pct >= 97', 'Sec.4.6', 'warn', 'Coverage block 2b (2026-09-29): "soll" → warn.', 'Der Verdichtungsgrad des Baugrundes soll DPr ≥ 97 % betragen.', false
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE w.code = 'FLL-GAR-06' AND s.code = 'FLL-GAR-2023'
ON CONFLICT (worksheet_template_id, code) DO NOTHING;
-- FLL-GAR-18 REQ-33 (new, warn) — "Empfohlene" / "geeignete" → warn (anhaltswert). The Tab.-25 fills already exist; this is the missing comparison.
INSERT INTO compliance_requirements (worksheet_template_id, code, title_de, title_en, condition, clause_reference, severity, description, source_quote, requires_attestation)
SELECT w.id, 'REQ-33', 'PE-Bahn — Nenndicke mindestens nach Tab. 25', 'PE liner — nominal thickness at least per Tab. 25', 'IF abdichtungs_art == bahn_pe THEN (pe_werkstoff == PELD AND pe_nenndicke_mm >= peld_nenndicke_min_mm) OR (pe_werkstoff == PEHD AND pe_nenndicke_mm >= pehd_nenndicke_min_mm)', 'Sec.6.4.1.2; Tab.25', 'warn', 'Coverage block 2b (2026-09-29): "Empfohlene" / "geeignete" → warn (anhaltswert). The Tab.-25 fills already exist; this is the missing comparison.', 'Tab. 25: Empfohlene Dicke von Dichtungsbahnen aus PELD und PEHD in Abhängigkeit der Beanspruchung (p. 96) — "Tabelle 25 gibt einen Überblick über geeignete Werkstoffdicken für PELD- und PEHD-Bahnen."', false
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE w.code = 'FLL-GAR-18' AND s.code = 'FLL-GAR-2023'
ON CONFLICT (worksheet_template_id, code) DO NOTHING;
-- FLL-GAR-18 REQ-34 (new, warn) — "sollten" → warn; the 1:10 trigger reads the steepest slope section (boeschung_steilste_1m, FLL-GAR-07-D1). RULING: the "Längen über 3 m" condition is not evaluated per row (register laenge_m exists; a row-level count would need a new derived).
INSERT INTO compliance_requirements (worksheet_template_id, code, title_de, title_en, condition, clause_reference, severity, description, source_quote, requires_attestation)
SELECT w.id, 'REQ-34', 'PE-Bahn — Verlegung auf Böschungen (§6.4.2)', 'PE liner — installation on slopes (§6.4.2)', 'IF abdichtungs_art == bahn_pe THEN (boeschung_steilste_1m > 10 OR pe_boeschung_strukturiert == true) AND pe_querueberlappung_vermieden == true AND pe_scherversuch_durchgefuehrt == true', 'Sec.6.4.2', 'warn', 'Coverage block 2b (2026-09-29): "sollten" → warn; the 1:10 trigger reads the steepest slope section (boeschung_steilste_1m, FLL-GAR-07-D1). RULING: the "Längen über 3 m" condition is not evaluated per row (register laenge_m exists; a row-level count would need a new derived).', 'Bei Böschungen ab Neigungen von 1:10 und Längen über 3 m sollten Kunststoffbahnen aus PEHD mit strukturierter Oberfläche in Böschungsfallrichtung verlegt werden. Querüberlappungen in Böschungsfallrichtung sind zu vermeiden. Bei Neigungen von 1:3,5 oder steiler sind ggf. verdeckte Bermen vorzusehen. In allen Fällen sollten die relevanten Kontaktreibungswinkel durch Scherversuche ermittelt werden.', false
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE w.code = 'FLL-GAR-18' AND s.code = 'FLL-GAR-2023'
ON CONFLICT (worksheet_template_id, code) DO NOTHING;
-- FLL-GAR-18 REQ-35 (new, block) — "sind … durchzuführen" / "sind zu protokollieren" → block (RULING).
INSERT INTO compliance_requirements (worksheet_template_id, code, title_de, title_en, condition, clause_reference, severity, description, source_quote, requires_attestation)
SELECT w.id, 'REQ-35', 'PE-Bahn — Probeschweißungen und protokollierte Nahtprüfung (§6.4.2.1)', 'PE liner — trial welds and recorded seam testing (§6.4.2.1)', 'IF abdichtungs_art == bahn_pe THEN pe_probeschweissung_durchgefuehrt == true AND pe_nahtpruefung_protokoll == true', 'Sec.6.4.2.1', 'block', 'Coverage block 2b (2026-09-29): "sind … durchzuführen" / "sind zu protokollieren" → block (RULING).', 'Die Nahtüberlappung sollte je nach verwendetem Schweißautomaten zwischen 100 und 150 mm betragen. Vor der Verschweißung sind Probeschweißungen durchzuführen, um die Schweißgeräte und auch die Nahtqualität zu beurteilen. Die Probeschweißungen sollen unter Baustellenbedingungen ausgeführt werden. Die Probeschweißungen sind idealerweise 1,0 m lang und 30 cm breit mit mittiger Schweißnaht. Alle Nähte müssten zerstörungsfrei auf ihr äußeres Erscheinungsbild über die gesamte Länge der Naht geprüft werden. Als Verfahren zur Nahtprüfung eignen sich z. B. die Druckluftprüfung für Doppelnähte und die Vakuumprüfung für Extrusionsschweißnähte. Die Prüfergebnisse sind zu protokollieren.', false
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE w.code = 'FLL-GAR-18' AND s.code = 'FLL-GAR-2023'
ON CONFLICT (worksheet_template_id, code) DO NOTHING;
-- FLL-GAR-18 REQ-36 (new, warn) — "sollte" → warn. Field naht_pe_ueberlappung_mm exists (required) but was never compared.
INSERT INTO compliance_requirements (worksheet_template_id, code, title_de, title_en, condition, clause_reference, severity, description, source_quote, requires_attestation)
SELECT w.id, 'REQ-36', 'PE-Bahn — Nahtüberlappung 100–150 mm (§6.4.2.1)', 'PE liner — seam overlap 100–150 mm (§6.4.2.1)', 'IF abdichtungs_art == bahn_pe THEN naht_pe_ueberlappung_mm >= 100 AND naht_pe_ueberlappung_mm <= 150', 'Sec.6.4.2.1', 'warn', 'Coverage block 2b (2026-09-29): "sollte" → warn. Field naht_pe_ueberlappung_mm exists (required) but was never compared.', 'Die Nahtüberlappung sollte je nach verwendetem Schweißautomaten zwischen 100 und 150 mm betragen.', false
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE w.code = 'FLL-GAR-18' AND s.code = 'FLL-GAR-2023'
ON CONFLICT (worksheet_template_id, code) DO NOTHING;
-- FLL-GAR-18 REQ-37 (new, block) — "dürfen … nicht breiter" / "höchstens" → block (RULING). Guard: only when cracks are not excluded (neurissbildung, FLL-GAR-05) — an earth pond without structures leaves the three fields empty and must not be blocked.
INSERT INTO compliance_requirements (worksheet_template_id, code, title_de, title_en, condition, clause_reference, severity, description, source_quote, requires_attestation)
SELECT w.id, 'REQ-37', 'PE-Bahn — Rissüberdeckung am Bauwerk (§6.4.2.2)', 'PE liner — crack bridging at the structure (§6.4.2.2)', 'IF abdichtungs_art == bahn_pe AND NOT (neurissbildung == ausgeschlossen) THEN pe_riss_entstehung_mm <= 0.5 AND pe_riss_aufweitung_mm <= 2.0 AND pe_riss_versatz_mm <= 1.0', 'Sec.6.4.2.2', 'block', 'Coverage block 2b (2026-09-29): "dürfen … nicht breiter" / "höchstens" → block (RULING). Guard: only when cracks are not excluded (neurissbildung, FLL-GAR-05) — an earth pond without structures leaves the three fields empty and must not be blocked.', 'Arbeitsfugen oder Risse von abzudichtenden Bauwerken dürfen zum Zeitpunkt ihrer Entstehung nicht breiter als 0,5 mm sein. Durch eventuelle weitere Bewegung ist eine Aufweitung auf höchstens 2,0 mm und ein Versatz der Risskanten auf höchstens 1,0 mm zulässig. Kunststoffbahnen aus PEHD müssen vorgenannte Risse im Bauwerk überbrücken können.', false
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE w.code = 'FLL-GAR-18' AND s.code = 'FLL-GAR-2023'
ON CONFLICT (worksheet_template_id, code) DO NOTHING;
-- FLL-GAR-20 REQ-38 (new, block) — "entsprechen den Anforderungen gemäß Abschnitt 5.1.1" + "beträgt ≥ 97 %" → block (RULING: Tab. 3 row 2 Kornanteil < 0,002 mm is replaced by < 0,063 mm per §7.2.1.1 and stays in REQ-22; row 7 Einbauwassergehalt not repeated here).
INSERT INTO compliance_requirements (worksheet_template_id, code, title_de, title_en, condition, clause_reference, severity, description, source_quote, requires_attestation)
SELECT w.id, 'REQ-38', 'Alkalisilikate — Tab.-3-Anforderungen der vergüteten Dichtungsschicht (§7.2.1.1 → §5.1.1)', 'Alkali silicates — Tab. 3 requirements of the treated sealing layer (§7.2.1.1 → §5.1.1)', 'IF abdichtungs_art == alkalisilikat THEN as_dpr_pct >= 97 AND as_kf_m_s <= 0.000000001 AND as_organische_substanz_VGL <= 5 AND as_kalkgehalt_VCA <= 15', 'Sec.7.2.1.1; Sec.7.2.2.1; Tab.3', 'block', 'Coverage block 2b (2026-09-29): "entsprechen den Anforderungen gemäß Abschnitt 5.1.1" + "beträgt ≥ 97 %" → block (RULING: Tab. 3 row 2 Kornanteil < 0,002 mm is replaced by < 0,063 mm per §7.2.1.1 and stays in REQ-22; row 7 Einbauwassergehalt not repeated here).', 'Auf homogene Mineralbodenverhältnisse innerhalb der Abdichtung ist zu achten. Der Feinkornanteil < 0,063 mm des anstehenden Bodens soll mind. 20 Masse-% betragen. Zur Anwendung kommen dabei die Prüfungen nach Abschnitt 5.1.1. Abweichend davon ist der Kornanteil < 0,063 mm zu bestimmen. […] Die Anforderungen an die vergütete Dichtungsschicht entsprechen den Anforderungen gemäß Abschnitt 5.1.1. Zur Homogenisierung des Baugrundes ist eine Durchmischung des abzudichtenden Bodenschicht, z. B. durch Auffräsen, vorzusehen. Die Lockerungstiefe soll mind. 25 cm betragen. […] Die Dichtungsschicht ist dynamisch und statisch zu verdichten. Die Lagerungsdichte DPr beträgt ≥ 97 %.', false
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE w.code = 'FLL-GAR-20' AND s.code = 'FLL-GAR-2023'
ON CONFLICT (worksheet_template_id, code) DO NOTHING;
-- FLL-GAR-16 REQ-39 (new, block) — "einzuhalten" → block (RULING). naht_verletzungen (FLL-GAR-16-D1) already counts rows under the Tab.-22 minimum; an empty register yields 0 (vacuous) — RULING whether ≥ 1 seam row should be required.
INSERT INTO compliance_requirements (worksheet_template_id, code, title_de, title_en, condition, clause_reference, severity, description, source_quote, requires_attestation)
SELECT w.id, 'REQ-39', 'Kunststoff-/Elastomerbahnen — Mindestfügebreite aller Nähte nach Tab. 22', 'Plastic / elastomer sheets — minimum joint width of all seams per Tab. 22', 'IF abdichtungs_art == bahn_kunststoff_elastomer THEN naht_verletzungen == 0', 'Sec.6.2.2.1; Tab.22', 'block', 'Coverage block 2b (2026-09-29): "einzuhalten" → block (RULING). naht_verletzungen (FLL-GAR-16-D1) already counts rows under the Tab.-22 minimum; an empty register yields 0 (vacuous) — RULING whether ≥ 1 seam row should be required.', 'Je nach Stoffart der Kunststoff- und Elastomerbahn sind unterschiedliche Fügeverfahren und Mindestfügebreiten einzuhalten. (Tab. 22, p. 85)', false
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE w.code = 'FLL-GAR-16' AND s.code = 'FLL-GAR-2023'
ON CONFLICT (worksheet_template_id, code) DO NOTHING;
-- FLL-GAR-27 REQ-40 (new, block) — "ist … zu dimensionieren" → block (RULING; Anhang 1 is informativ — the "höher als Regelüberlauf" clause comes from the Anhang, not from §4.10).
INSERT INTO compliance_requirements (worksheet_template_id, code, title_de, title_en, condition, clause_reference, severity, description, source_quote, requires_attestation)
SELECT w.id, 'REQ-40', 'Notüberlauf an aufgehenden Gebäudeteilen — vorhanden, höher als Regelüberlauf, Kapazität ≥ Q_NOT', 'Emergency overflow at rising building parts — present, above the regular overflow, capacity ≥ Q_NOT', 'IF gewaesser_an_gebaeudeteilen == true THEN notueberlauf_vorhanden == true AND notueberlauf_hoeher_als_regelueberlauf == true AND notueberlauf_kapazitaet_l_s >= Q_NOT', 'Sec.4.10; Anhang 1', 'block', 'Coverage block 2b (2026-09-29): "ist … zu dimensionieren" → block (RULING; Anhang 1 is informativ — the "höher als Regelüberlauf" clause comes from the Anhang, not from §4.10).', 'Werden Gewässer an aufgehenden Gebäudeteilen ausgeführt, ist ein Notüberlauf mit kanalunabhängigem Entwässerungskonzept nach DIN 1986-100 mit örtlicher 100-Jahres-Regenspende r5,100 zu dimensionieren. Der Notüberlauf ist als kanalunabhängige Notentwässerung höher als der Regelüberlauf einzubauen.', false
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE w.code = 'FLL-GAR-27' AND s.code = 'FLL-GAR-2023'
ON CONFLICT (worksheet_template_id, code) DO NOTHING;
COMMIT;
